window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-defc290b9deca73b"]={"versions": [{"id": "FIG-defc290b9deca73b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software & Systems Process Engineering Metamodel) der AUTOSAR-Methodik zur Spezifikation des methodischen Arbeitsschritts „Define BSW Interfaces“ im Kontext der Basissoftware-Entwicklung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität</strong>: <code>Define BSW Interfaces</code> (zentraler Prozessschritt).</li>\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Designer</code> (Assoziation <code>«performs»</code>, Multiplizität <code>1</code>).</li>\n<li><code>Basic Software Module Developer</code> (Assoziation <code>«performs»</code>, Multiplizität <code>0..1</code>).</li>\n<li><strong>Eingangs-Artefakte (<code>«input»</code>)</strong>:</li>\n<li><code>BSW Types</code> (Dokumentsymbol, Multiplizität <code>1</code>).</li>\n<li><code>BSW Standard Package</code> (Paket-/Umschlagsymbol, Multiplizität <code>0..1</code>).</li>\n<li><code>Basic Software Entries</code> (Dokumentsymbol, Multiplizität <code>1</code>).</li>\n<li><code>ECU Resources Description</code> (Dokumentsymbol, Multiplizität <code>0..1</code>).</li>\n<li><strong>Ausgangs-Artefakt (<code>«output»</code>)</strong>:</li>\n<li><code>Basic Software Module Description</code> (Dokumentsymbol rechts, Text am Rand abgeschnitten als <code>Basic Software M...</code>, Multiplizität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define BSW Interfaces</code> wird obligatorisch durch den <code>Basic Software Designer</code> ausgeführt, optional unterstützt durch den <code>Basic Software Module Developer</code>. Als verbindliche Eingangsdaten fließen <code>BSW Types</code> und <code>Basic Software Entries</code> (jeweils Multiplizität <code>1</code>) ein, während <code>BSW Standard Package</code> sowie die <code>ECU Resources Description</code> optional beigesteuert werden (<code>0..1</code>). Das Ergebnis der Aktivität ist genau eine <code>Basic Software Module Description</code> (<code>«output» 1</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Multiplizitäten definieren strenge Anforderungen an den Entwicklungsprozess: Vor Ausführung von <code>Define BSW Interfaces</code> müssen die standardisierten Typdefinitionen (<code>BSW Types</code>) und Funktions-/Schnittstelleneinträge (<code>Basic Software Entries</code>) vorliegen. Das Fehlen von <code>BSW Standard Package</code> oder <code>ECU Resources Description</code> blockiert die Ausführung nicht, kann aber den Detaillierungsgrad der generierten <code>Basic Software Module Description</code> beeinflussen.</p>"}, {"id": "FIG-8ef5931b217b0674", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software & Systems Process Engineering Metamodel) der AUTOSAR-Methodik zur Spezifikation des methodischen Arbeitsschritts „Define BSW Interfaces“ im Kontext der Basissoftware-Entwicklung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität</strong>: <code>Define BSW Interfaces</code> (zentraler Prozessschritt).</li>\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Designer</code> (Assoziation <code>«performs»</code>, Multiplizität <code>1</code>).</li>\n<li><code>Basic Software Module Developer</code> (Assoziation <code>«performs»</code>, Multiplizität <code>0..1</code>).</li>\n<li><strong>Eingangs-Artefakte (<code>«input»</code>)</strong>:</li>\n<li><code>BSW Types</code> (Dokumentsymbol, Multiplizität <code>1</code>).</li>\n<li><code>BSW Standard Package</code> (Paket-/Umschlagsymbol, Multiplizität <code>0..1</code>).</li>\n<li><code>Basic Software Entries</code> (Dokumentsymbol, Multiplizität <code>1</code>).</li>\n<li><code>ECU Resources Description</code> (Dokumentsymbol, Multiplizität <code>0..1</code>).</li>\n<li><strong>Ausgangs-Artefakt (<code>«output»</code>)</strong>:</li>\n<li><code>Basic Software Module Description</code> (Dokumentsymbol rechts, Text am Rand abgeschnitten als <code>Basic Software M...</code>, Multiplizität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define BSW Interfaces</code> wird obligatorisch durch den <code>Basic Software Designer</code> ausgeführt, optional unterstützt durch den <code>Basic Software Module Developer</code>. Als verbindliche Eingangsdaten fließen <code>BSW Types</code> und <code>Basic Software Entries</code> (jeweils Multiplizität <code>1</code>) ein, während <code>BSW Standard Package</code> sowie die <code>ECU Resources Description</code> optional beigesteuert werden (<code>0..1</code>). Das Ergebnis der Aktivität ist genau eine <code>Basic Software Module Description</code> (<code>«output» 1</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Multiplizitäten definieren strenge Anforderungen an den Entwicklungsprozess: Vor Ausführung von <code>Define BSW Interfaces</code> müssen die standardisierten Typdefinitionen (<code>BSW Types</code>) und Funktions-/Schnittstelleneinträge (<code>Basic Software Entries</code>) vorliegen. Das Fehlen von <code>BSW Standard Package</code> oder <code>ECU Resources Description</code> blockiert die Ausführung nicht, kann aber den Detaillierungsgrad der generierten <code>Basic Software Module Description</code> beeinflussen.</p>"}], "trans": [{"from": "FIG-defc290b9deca73b", "to": "FIG-8ef5931b217b0674", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
